let sins;

function setup() {
  createCanvas(innerWidth, innerHeight);
  sins = [];
  for (let i = 0; i < 10; i++) {
    sins.push(new Sin());
  }
}

function draw() {
  background(32);
  stroke(32, 192, 128)
  noFill();
  translate(0, height * 0.5)
  let sum = [];
  for (let i = 0; i < sins.length; i++) {
    const s = sins[i];
    s.update();
    let tmpA = s.get();
    for (let j = 0; j < tmpA.length; j++) {
      sum[j] = sum[j] ? sum[j] + tmpA[j] : tmpA[j]
    }
  }

  beginShape()
  for (let x = 0; x < sum.length; x++) {
    vertex(x, sum[x])
  } 
  endShape();
}

class Sin {
  constructor() {
    this.ang = random(TWO_PI);
    this.da = random(random(random(TWO_PI)))
    this.scl = random(0.001, 0.1);
    this.amp = random(height*0.05, height*0.25)
  }

  update() {
    this.ang += this.da;
  }

  get() {
    let arr = [];
    for (let x = 0; x < width; x++) {
      const y = sin(this.ang + x * this.scl) * this.amp;
      arr.push(y)
    }
    return arr;
  }

  show() {
    push();
    var arr = this.get();
    beginShape()
    for (let x = 0; x < width; x++) {
      // const y = sin(this.ang + x * this.scl) * this.amp;
      vertex(x, arr[x])
    }
    endShape();
    pop();
  }
}
